# typed: false
# frozen_string_literal: true

# Homebrew formula for the Engra CLI. Generated by packaging/release.py in the
# release workflow; do not hand-edit. Release assets live in
# arenberg-engineering/engra-releases.
class Engra < Formula
  desc "AI coding agent and developer assistant for the terminal"
  homepage "https://engra.io"
  # Proprietary software of Arenberg AG, all rights reserved (LICENSE.txt).
  license :cannot_represent

  livecheck do
    url :stable
    strategy :github_latest
  end

  on_macos do
    on_arm do
      url "https://github.com/arenberg-engineering/engra-releases/releases/download/v0.4.15/engra-0.4.15-macos-arm64.tar.gz"
      sha256 "cade584deaf43701e549766815a30c5695af6d7a1efcfd044840f056a7b3e751"
    end
    on_intel do
      url "https://github.com/arenberg-engineering/engra-releases/releases/download/v0.4.15/engra-0.4.15-macos-x64.tar.gz"
      sha256 "b66095e3ca9d0b415968876f7b2e723cf94ddfcd7dcd05fd9bf0cfe38cff9c0f"
    end
  end

  on_linux do
    on_arm do
      url "https://github.com/arenberg-engineering/engra-releases/releases/download/v0.4.15/engra-0.4.15-linux-arm64.tar.gz"
      sha256 "396eea4b122837cf8c2c8f75197c2e8b5074e80f1c9767d509aeacb6c951b79b"
    end
    on_intel do
      url "https://github.com/arenberg-engineering/engra-releases/releases/download/v0.4.15/engra-0.4.15-linux-x64.tar.gz"
      sha256 "3d2bd1b2a001969e673262e0b16e365c9fb7200e96fe2ed53e968f36c682ea5f"
    end
  end

  def install
    libexec.install "engra", "_internal"
    bin.install_symlink libexec/"engra"
    prefix.install "LICENSE.txt", "TERMS.md", "THIRD_PARTY_NOTICES.txt"
  end

  def caveats
    <<~EOS
      Sign in with:
        engra login

      Terms of Use: engra legal --terms

      Before uninstalling, run `engra logout` to remove saved credentials from
      the OS keychain. Settings and link state stay in ~/.config/engra (and
      doctor records in ~/.engra); remove them to clear everything.
    EOS
  end

  test do
    assert_equal "engra #{version}", shell_output("#{bin}/engra --version").strip
    assert_match "doctor", shell_output("#{bin}/engra --help")
    assert_match "Arenberg AG", shell_output("#{bin}/engra legal")
  end
end
